import sys,random,pickle
sys.path.insert(0,'/workspace/project')
from ebpf.helper import Agent
from syntax import parse_policy

services=[{'name':'A','label':1},{'name':'B','label':2}]
limits={'images':3,'cells':20,'units':3,'contexts':6,'connections':2,'packets':4,'files':2}
policies=['','match(A) allow;','match(B) allow;','startswith(A) allow;','contains(B) allow;','endswith(A) allow;','not(match(A)) allow;','(startswith(A) and contains(B)) allow;','startswith() allow;','match(A) drop;','match(A) allow;match(A) drop;','(contains(A) or contains(B)) allow;']
random.seed(123)
for trial in range(200):
 a=Agent(services,limits)
 # stage some images, commit
 evs=[]
 ep=0
 for _ in range(random.randrange(0,4)):
  ep+=1
  pol=random.choice(policies)
  a.event({'op':'stage','epoch':ep,'policy':pol},parsed=parse_policy(pol))
  evs.append(('stage',ep))
 if ep and random.random()<.8:a.event({'op':'commit','epoch':random.randint(1,ep)})
 # random identities known alive counters
 unit_counter=0;conn_counter=0
 for step in range(300):
  before=pickle.dumps(a)
  op=random.choice(['commit','retire','spawn','clone','exit','begin','finish','open','close','send','recv','store','load','unlink','inspect','stage'])
  # generate candidates broadly
  if op=='stage':
   ep=random.randint(1,10);pol=random.choice(policies)
   e={'op':'stage','epoch':ep,'policy':pol};parsed=parse_policy(pol)
  elif op in ('commit','retire'):e={'op':op,'epoch':random.randint(1,10)};parsed=None
  elif op=='spawn':
   unit_counter+=1;e={'op':'spawn','unit':[0,unit_counter,random.randint(1,3)],'service':random.choice(['A','B','C'])};parsed=None
  elif op=='clone':
   # use existing pairs/gens often
   if a.units:
    uu=random.choice(list(a.units.values()));parent=[uu.ns,uu.pid,uu.gen]
   else:parent=[0,1,1]
   unit_counter+=1;e={'op':'clone','parent':parent,'child':[0,unit_counter,random.randint(1,3)]};parsed=None
  elif op in ('exit','begin','finish','send','store'):
   if a.units:
    uu=random.choice(list(a.units.values()));u=[uu.ns,uu.pid,uu.gen];rid=random.choice(list(uu.contexts.keys()) or [1])
   else:u=[0,1,1];rid=1
   if op=='exit':e={'op':'exit','unit':u}
   elif op=='begin':e={'op':'begin','unit':u,'rid':rid}
   elif op=='finish':e={'op':'finish','unit':u,'rid':rid}
   elif op=='store':e={'op':'store','unit':u,'rid':rid,'file':[random.randint(1,3),random.randint(1,4)]}
   else:e={'op':'send','unit':u,'rid':rid,'connection':[random.randint(1,3),random.randint(1,3)],'stream':random.randint(1,5),'destination':random.choice(['A','B','C'])}
   parsed=None
  elif op in ('open','close'):
   e={'op':op,'connection':[random.randint(1,3),random.randint(1,3)]};parsed=None
  elif op=='recv':
   if a.units:
    uu=random.choice(list(a.units.values()));u=[uu.ns,uu.pid,uu.gen]
   else:u=[0,1,1]
   wire=random.choice([None,'0'*48,'454d4334'+'0'*40])
   e={'op':'recv','connection':[random.randint(1,3),random.randint(1,3)],'stream':random.randint(1,5),'unit':u,'rid':random.randint(1,5),'wire':wire};parsed=None
  elif op=='load':e={'op':'load','file':[random.randint(1,3),random.randint(1,4)],'unit':([0,random.randint(1,unit_counter or 1),random.randint(1,3)]),'rid':random.randint(1,5)};parsed=None
  elif op=='unlink':e={'op':'unlink','file':[random.randint(1,3),random.randint(1,4)]};parsed=None
  else:e={'op':'inspect'};parsed=None
  r=a.event(e,parsed=parsed)
  if r.get('error'):
   after=pickle.dumps(a)
   if before!=after:
    print('ATOMIC FAIL',trial,step,e);print(r);raise SystemExit
  # invariants
  refs={ep:0 for ep in a.images}
  ccount=0
  for uu in a.units.values():
   ccount+=len(uu.contexts)
   for ctx in uu.contexts.values():refs[ctx.epoch]+=1
  pcount=0
  for cc in a.connections.values():
   pcount+=len(cc.packets)
   for p in cc.packets.values():refs[p.epoch]+=1
  for f in a.files.values():refs[f.epoch]+=1
  if ccount!=a.context_count or pcount!=a.packet_count:
   print('COUNT FAIL',trial,step,e,ccount,a.context_count,pcount,a.packet_count);raise SystemExit
  if len(a.files)!=len(a.files):pass
  for ep,rec in a.images.items():
   if refs[ep]!=rec.refs:
    print('REF FAIL',trial,step,e,ep,refs[ep],rec.refs);raise SystemExit
  if sum(r.cell_count for r in a.images.values())!=a.cells_used:
   print('CELL FAIL',trial,step,e);raise SystemExit
print('agent invariants/atomicity ok')
